import { Effect } from "effect"
import { Command, Flag } from "effect/unstable/cli"

export const publishingFlags = {
  registry: Flag.string("registry").pipe(
    Flag.withDefault("https://registry.example.com")
  ),
  channel: Flag.string("channel").pipe(Flag.withDefault("stable")),
  dryRun: Flag.boolean("dry-run")
}

export const publishCommand = Command.make(
  "publish",
  {
    ...publishingFlags,
    packagePath: Flag.string("package")
  },
  ({ registry, channel, dryRun, packagePath }) =>
    Effect.gen(function*() {
      yield* Effect.log(`Publishing ${packagePath} to ${registry}`)
      yield* Effect.log(`Release channel: ${channel}`)
      if (dryRun) {
        yield* Effect.log("Skipping upload")
      }
    })
)

export const checkPublishCommand = Command.make(
  "check-publish",
  {
    ...publishingFlags,
    strict: Flag.boolean("strict")
  },
  ({ registry, channel, dryRun, strict }) =>
    Effect.gen(function*() {
      yield* Effect.log(`Checking publication access to ${registry}`)
      yield* Effect.log(`Release channel: ${channel}`)
      yield* Effect.log(`Strict checks: ${strict}`)
      if (dryRun) {
        yield* Effect.log("Skipping write-access probe")
      }
    })
)

